  1	package shop;
  2	
  3	import com.fasterxml.jackson.databind.JsonNode;
  4	import com.fasterxml.jackson.databind.ObjectMapper;
  5	import io.javalin.Javalin;
  6	import org.junit.jupiter.api.AfterEach;
  7	import org.junit.jupiter.api.BeforeEach;
  8	import org.junit.jupiter.api.Test;
  9	import shop.shipping.CarrierGateway;
 10	import shop.shipping.CarrierQuote;
 11	
 12	import java.net.URI;
 13	import java.net.http.HttpClient;
 14	import java.net.http.HttpRequest;
 15	import java.net.http.HttpResponse;
 16	import java.time.Clock;
 17	import java.time.Instant;
 18	import java.time.ZoneOffset;
 19	import java.util.concurrent.atomic.AtomicReference;
 20	import java.util.function.Supplier;
 21	
 22	import static org.junit.jupiter.api.Assertions.assertEquals;
 23	
 24	class ServiceTest {
 25	    static final ObjectMapper JSON = new ObjectMapper();
 26	
 27	    InMemoryStore store;
 28	    Javalin app;
 29	    HttpClient http = HttpClient.newHttpClient();
 30	    AtomicReference<Supplier<CarrierQuote>> carrier = new AtomicReference<>();
 31	    int port;
 32	
 33	    @BeforeEach
 34	    void start() {
 35	        store = new InMemoryStore();
 36	        CarrierGateway gateway = (zip, grams, service) -> carrier.get().get();
 37	        app = App.create(store, gateway, Clock.fixed(Instant.parse("2026-10-14T15:30:00Z"), ZoneOffset.UTC)).start(0);
 38	        port = app.port();
 39	    }
 40	
 41	    @AfterEach
 42	    void stop() {
 43	        app.stop();
 44	    }
 45	
 46	    void carrierReplies(int cents, int hours) {
 47	        carrier.set(() -> new CarrierQuote(java.math.BigDecimal.valueOf(cents, 2), hours));
 48	    }
 49	
 50	    record Reply(int status, JsonNode body) {
 51	    }
 52	
 53	    Reply call(String method, String path, String body) throws Exception {
 54	        HttpRequest.Builder b = HttpRequest.newBuilder(URI.create("http://localhost:" + port + path));
 55	        b.method(method, body == null ? HttpRequest.BodyPublishers.noBody() : HttpRequest.BodyPublishers.ofString(body));
 56	        HttpResponse<String> r = http.send(b.build(), HttpResponse.BodyHandlers.ofString());
 57	        return new Reply(r.statusCode(), JSON.readTree(r.body()));
 58	    }
 59	
 60	    static String purchase(String items, String shipping, String coupon, String payment, int installments,
 61	                           String tier, String region) {
 62	        return """
 63	                {"customer":{"cpf":"12345678909","email":"ana@exemplo.com"},"items":%s,"zipCode":"01310100",
 64	                 "region":"%s","shippingMethod":"%s",%s"paymentMethod":"%s","installments":%d,"clubTier":"%s"}"""
 65	                .formatted(items, region, shipping, coupon == null ? "" : "\"coupon\":\"" + coupon + "\",", payment,
 66	                        installments, tier);
 67	    }
 68	
 69	    void assertSummary(String request, String expected) throws Exception {
 70	        Reply r = call("POST", "/checkout/summary", request);
 71	        assertEquals(200, r.status(), r.body().toString());
 72	        JsonNode e = JSON.readTree(expected);
 73	        e.fieldNames().forEachRemaining(f -> assertEquals(e.get(f).decimalValue().compareTo(r.body().get(f).decimalValue()), 0,
 74	                f + " in " + r.body()));
 75	        assertEquals(e.get("finalTotal").asText(), r.body().get("finalTotal").asText());
 76	    }
 77	
 78	    static final String CAM2_TEN1 = "[{\"sku\":\"CAM-001\",\"quantity\":2},{\"sku\":\"TEN-001\",\"quantity\":1}]";
 79	
 80	    @Test
 81	    void example1() throws Exception {
 82	        carrierReplies(3310, 41);
 83	        assertSummary(purchase(CAM2_TEN1, "EXPRESS", "WELCOME10", "PIX", 1, "BRONZE", "NORTH"),
 84	                "{\"productsSubtotal\":409.70,\"couponDiscount\":40.97,\"shippingCost\":33.10,\"deliveryDays\":5,"
 85	                        + "\"insurance\":10.24,\"paymentAdjustment\":0.00,\"finalTotal\":412.07,\"installmentAmount\":412.07,"
 86	                        + "\"nextPurchaseCredit\":0.00,\"gift\":false}");
 87	    }
 88	
 89	    @Test
 90	    void example2() throws Exception {
 91	        carrierReplies(1560, 168);
 92	        assertSummary(purchase(CAM2_TEN1, "ECONOMY", null, "CREDIT_CARD", 6, "SILVER", "MIDWEST"),
 93	                "{\"shippingCost\":15.60,\"deliveryDays\":7,\"insurance\":6.15,\"paymentAdjustment\":30.55,"
 94	                        + "\"finalTotal\":462.00,\"installments\":6,\"installmentAmount\":77.00,\"nextPurchaseCredit\":8.19}");
 95	    }
 96	
 97	    @Test
 98	    void example3() throws Exception {
 99	        assertSummary(purchase("[{\"sku\":\"FON-001\",\"quantity\":2}]", "COURIER", "MINUS50", "BANK_SLIP", 1, "GOLD", "NORTHEAST"),
100	                "{\"productsSubtotal\":399.80,\"couponDiscount\":50.00,\"shippingCost\":18.00,\"deliveryDays\":0,"
101	                        + "\"insurance\":8.00,\"paymentAdjustment\":3.49,\"finalTotal\":379.29,\"nextPurchaseCredit\":19.99}");
102	    }
103	
104	    @Test
105	    void example4() throws Exception {
106	        assertSummary(purchase("[{\"sku\":\"MEI-001\",\"quantity\":7},{\"sku\":\"CAM-001\",\"quantity\":2}]", "STORE_PICKUP",
107	                        "BUY3PAY2", "CREDIT_CARD", 3, "SILVER", "SOUTH"),
108	                "{\"productsSubtotal\":299.10,\"couponDiscount\":39.80,\"deliveryDays\":1,\"insurance\":2.99,"
109	                        + "\"finalTotal\":262.29,\"installmentAmount\":87.43,\"nextPurchaseCredit\":5.98}");
110	    }
111	
112	    @Test
113	    void example5() throws Exception {
114	        carrierReplies(2475, 30);
115	        assertSummary(purchase("[{\"sku\":\"CAM-001\",\"quantity\":3}]", "EXPRESS", "BUY3PAY2", "PIX", 1, "BRONZE", "SOUTHEAST"),
116	                "{\"couponDiscount\":71.91,\"shippingCost\":24.75,\"deliveryDays\":2,\"insurance\":2.40,\"finalTotal\":194.94}");
117	    }
118	
119	    @Test
120	    void example6() throws Exception {
121	        carrierReplies(2210, 150);
122	        assertSummary(purchase("[{\"sku\":\"MEI-001\",\"quantity\":1}]", "ECONOMY", "FREESHIPPING", "BANK_SLIP", 1, "BRONZE", "SOUTH"),
123	                "{\"couponDiscount\":5.97,\"shippingCost\":22.10,\"deliveryDays\":7,\"insurance\":0.20,"
124	                        + "\"paymentAdjustment\":3.49,\"finalTotal\":39.72}");
125	    }
126	
127	    @Test
128	    void example7() throws Exception {
129	        carrierReplies(5080, 49);
130	        store.products.put("JAQ-001", new shop.catalog.Product("JAQ-001", "J", new java.math.BigDecimal("389.90"),
131	                new java.math.BigDecimal("0.80"), 10, false));
132	        assertSummary(purchase("[{\"sku\":\"JAQ-001\",\"quantity\":3},{\"sku\":\"TEN-001\",\"quantity\":1}]", "EXPRESS", null,
133	                        "PIX", 1, "GOLD", "NORTH"),
134	                "{\"productsSubtotal\":1419.60,\"shippingCost\":0.00,\"deliveryDays\":6,\"insurance\":30.00,"
135	                        + "\"paymentAdjustment\":-72.48,\"finalTotal\":1377.12,\"nextPurchaseCredit\":70.98,\"gift\":true}");
136	    }
137	
138	    @Test
139	    void refusals() throws Exception {
140	        Reply r = call("POST", "/checkout/summary",
141	                purchase("[{\"sku\":\"CAM-001\",\"quantity\":1}]", "STORE_PICKUP", "FREESHIPPING", "PIX", 1, "SILVER", "SOUTHEAST"));
142	        assertEquals(422, r.status());
143	        assertEquals("COUPON_NOT_APPLICABLE", r.body().get("error").asText());
144	
145	        carrier.set(() -> {
146	            throw ApiException.unprocessable("SHIPPING_METHOD_UNAVAILABLE");
147	        });
148	        r = call("POST", "/checkout/summary",
149	                purchase("[{\"sku\":\"TEN-001\",\"quantity\":1}]", "ECONOMY", null, "PIX", 1, "BRONZE", "NORTH"));
150	        assertEquals("SHIPPING_METHOD_UNAVAILABLE", r.body().get("error").asText());
151	
152	        carrier.set(() -> {
153	            throw ApiException.unavailable("CARRIER_UNAVAILABLE");
154	        });
155	        r = call("POST", "/checkout/summary",
156	                purchase("[{\"sku\":\"TEN-001\",\"quantity\":1}]", "ECONOMY", null, "PIX", 1, "BRONZE", "NORTH"));
157	        assertEquals(503, r.status());
158	
159	        r = call("POST", "/checkout/summary", purchase("[{\"sku\":\"REL-001\",\"quantity\":1}]", "COURIER", null, "PIX", 1, "BRONZE", "NORTH"));
160	        assertEquals("PRODUCT_DISCONTINUED", r.body().get("error").asText());
161	        r = call("POST", "/checkout/summary", purchase("[{\"sku\":\"BON-001\",\"quantity\":1}]", "COURIER", "", "PIX", 1, "BRONZE", "NORTH"));
162	        assertEquals("INSUFFICIENT_STOCK", r.body().get("error").asText());
163	        r = call("POST", "/checkout/summary", purchase("[{\"sku\":\"CAM-001\",\"quantity\":1}]", "COURIER", "", "PIX", 1, "BRONZE", "NORTH"));
164	        assertEquals("INVALID_COUPON", r.body().get("error").asText());
165	        r = call("POST", "/checkout/summary", purchase("[{\"sku\":\"CAM-001\",\"quantity\":1}]", "COURIER", null, "PIX", 2, "BRONZE", "NORTH"));
166	        assertEquals("INVALID_INSTALLMENTS", r.body().get("error").asText());
167	        r = call("POST", "/checkout/summary", "{}");
168	        assertEquals("INVALID_ORDER", r.body().get("error").asText());
169	    }
170	
171	    String register(String items, String tier) throws Exception {
172	        carrierReplies(1000, 24);
173	        Reply r = call("POST", "/orders", purchase(items, "ECONOMY", null, "PIX", 1, tier, "SOUTHEAST"));
174	        assertEquals(201, r.status(), r.body().toString());
175	        assertEquals("AWAITING_PAYMENT", r.body().get("status").asText());
176	        return r.body().get("id").asText();
177	    }
178	
179	    String pay(String id, String tx, String at) {
180	        return "{\"transactionId\":\"" + tx + "\",\"paidAt\":\"" + at + "\"}";
181	    }
182	
183	    @Test
184	    void paymentIsIdempotentAndMovesStockAndCredit() throws Exception {
185	        String id = register("[{\"sku\":\"FON-001\",\"quantity\":2}]", "SILVER");
186	        Reply first = call("POST", "/orders/" + id + "/payment", pay(id, "TX-1", "2026-10-14T16:00:00Z"));
187	        assertEquals(200, first.status());
188	        assertEquals("PAID", first.body().get("status").asText());
189	        Reply again = call("POST", "/orders/" + id + "/payment", pay(id, "TX-1", "2026-10-14T16:00:00Z"));
190	        assertEquals(first.body(), again.body());
191	        assertEquals(3, store.products.get("FON-001").stock());
192	        assertEquals(0, new java.math.BigDecimal("8.00").compareTo(call("GET", "/customers/12345678909", null).body().get("creditBalance").decimalValue()));
193	        assertEquals(1, call("GET", "/customers/12345678909/notifications", null).body().size());
194	        assertEquals(409, call("POST", "/orders/" + id + "/payment", pay(id, "TX-2", "2026-10-14T16:00:00Z")).status());
195	
196	        Reply cancelled = call("POST", "/orders/" + id + "/cancellation", null);
197	        assertEquals("CANCELLED", cancelled.body().get("status").asText());
198	        assertEquals(5, store.products.get("FON-001").stock());
199	        assertEquals(0, call("GET", "/customers/12345678909", null).body().get("creditBalance").decimalValue().signum());
200	        assertEquals(2, call("GET", "/customers/12345678909/notifications", null).body().size());
201	    }
202	
203	    @Test
204	    void expiryBoundaryAndOutOfStock() throws Exception {
205	        String id = register("[{\"sku\":\"CAM-001\",\"quantity\":1}]", "BRONZE");
206	        String late = pay(id, "TX-9", "2026-10-16T15:30:01Z");
207	        Reply r = call("POST", "/orders/" + id + "/payment", late);
208	        assertEquals(409, r.status());
209	        assertEquals("ORDER_EXPIRED", r.body().get("error").asText());
210	        assertEquals("ORDER_EXPIRED", call("POST", "/orders/" + id + "/payment", late).body().get("error").asText());
211	        assertEquals("CANCELLED", call("GET", "/orders/" + id, null).body().get("status").asText());
212	
213	        String exact = register("[{\"sku\":\"MOC-001\",\"quantity\":1}]", "BRONZE");
214	        String other = register("[{\"sku\":\"MOC-001\",\"quantity\":1}]", "BRONZE");
215	        assertEquals(200, call("POST", "/orders/" + exact + "/payment", pay(exact, "A", "2026-10-16T15:30:00Z")).status());
216	        r = call("POST", "/orders/" + other + "/payment", pay(other, "B", "2026-10-14T16:00:00Z"));
217	        assertEquals("INSUFFICIENT_STOCK", r.body().get("error").asText());
218	        assertEquals(0, store.products.get("MOC-001").stock());
219	        assertEquals("CANCELLED", call("GET", "/orders/" + other, null).body().get("status").asText());
220	    }
221	
222	    @Test
223	    void shipmentFlow() throws Exception {
224	        String id = register("[{\"sku\":\"CAM-001\",\"quantity\":1}]", "BRONZE");
225	        assertEquals(409, call("POST", "/orders/" + id + "/shipment", "{\"trackingCode\":\"BR1\"}").status());
226	        call("POST", "/orders/" + id + "/payment", pay(id, "T", "2026-10-14T16:00:00Z"));
227	        assertEquals("INVALID_ORDER", call("POST", "/orders/" + id + "/shipment", "{}").body().get("error").asText());
228	        Reply shipped = call("POST", "/orders/" + id + "/shipment", "{\"trackingCode\":\"BR1\"}");
229	        assertEquals("BR1", shipped.body().get("trackingCode").asText());
230	        assertEquals(409, call("POST", "/orders/" + id + "/cancellation", null).status());
231	        assertEquals("DELIVERED", call("POST", "/orders/" + id + "/delivery", null).body().get("status").asText());
232	        assertEquals(404, call("GET", "/orders/nope", null).status());
233	        String note = call("GET", "/customers/12345678909/notifications", null).body().get(0).get("id").asText();
234	        assertEquals("READ", call("POST", "/notifications/" + note + "/read", null).body().get("status").asText());
235	    }
236	}

