 24	import shop.web.Routes;
 25	
 26	import java.time.Clock;
 27	import java.util.List;
 28	import java.util.Map;
 29	import java.util.function.Function;
 30	import java.util.stream.Collectors;
 31	
 32	/** Wires the service together. Adding a shipping option, coupon, payment method or payment reaction is a line here. */
 33	public final class App {
 34	    private App() {
 35	    }
 36	
 37	    public static Javalin create(Store store, CarrierGateway translog, Clock clock) {
 38	        Map<String, ShippingOption> shipping = byCode(List.of(
 39	                new CarrierShipping("ECONOMY", "STD", translog),
 40	                new CarrierShipping("EXPRESS", "EXP", translog),
 41	                new StorePickupShipping(),
 42	                new CourierShipping()), ShippingOption::code);
 43	        Map<String, Coupon> coupons = byCode(List.of(
 44	                new Welcome10Coupon(), new Minus50Coupon(), new FreeShippingCoupon(), new Buy3Pay2Coupon()), Coupon::code);
 45	        Map<String, PaymentOption> payments = byCode(List.of(
 46	                new PixPayment(), new CreditCardPayment(), new BankSlipPayment()), PaymentOption::code);
 47	
 48	        Notifier notifier = new Notifier();
 49	        OrderService orders = new OrderService(store, new CheckoutCalculator(shipping, coupons, payments), notifier,
 50	                List.of(new CreditReaction(), new PaymentApprovedNoticeReaction(notifier)), clock);
 51	
 52	        Javalin app = Javalin.create();
 53	        new Routes(orders, new QueryService(store)).register(app);
 54	        return app;
 55	    }
 56	
 57	    private static <T> Map<String, T> byCode(List<T> items, Function<T, String> code) {
 58	        return items.stream().collect(Collectors.toUnmodifiableMap(code, Function.identity()));
 59	    }
 60	}
 61	package shop;
 62	
 63	import com.zaxxer.hikari.HikariConfig;
 64	import com.zaxxer.hikari.HikariDataSource;
 65	import shop.persistence.PostgresStore;
 66	import shop.persistence.Schema;
 67	import shop.shipping.TransLogGateway;
 68	
 69	import java.time.Clock;
 70	
 71	public final class Main {
 72	    private Main() {
 73	    }
 74	
 75	    public static void main(String[] args) throws Exception {
 76	        HikariDataSource dataSource = connect();
 77	        Schema.init(dataSource);
 78	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "8080"));
 79	        App.create(new PostgresStore(dataSource), new TransLogGateway(System.getenv("TRANSLOG_URL")), Clock.systemUTC())
 80	                .start(port);
 81	    }
 82	
 83	    /** The database may still be starting when the service does, so it retries for a while. */
 84	    private static HikariDataSource connect() throws InterruptedException {
 85	        HikariConfig config = new HikariConfig();
 86	        config.setJdbcUrl(jdbcUrl(System.getenv("DB_URL")));
 87	        config.setUsername(System.getenv("DB_USER"));
 88	        config.setPassword(System.getenv("DB_PASSWORD"));
 89	        config.setMaximumPoolSize(10);
 90	        for (int attempt = 1; ; attempt++) {
 91	            try {
 92	                config.setInitializationFailTimeout(1);
 93	                return new HikariDataSource(config);
 94	            } catch (RuntimeException e) {
 95	                if (attempt >= 30) {
 96	                    throw e;
 97	                }
 98	                Thread.sleep(2000);
 99	            }
100	        }
101	    }
102	
103	    private static String jdbcUrl(String url) {
104	        if (url == null || url.startsWith("jdbc:")) {
105	            return url;
106	        }
107	        return "jdbc:" + url.replaceFirst("^postgres://", "postgresql://");
108	    }
109	}
  1	package shop.shipping;
  2	
  3	import com.fasterxml.jackson.databind.JsonNode;
  4	import com.fasterxml.jackson.databind.ObjectMapper;
  5	import shop.ApiException;
  6	
  7	import java.io.IOException;
  8	import java.math.BigDecimal;
  9	import java.net.URI;
 10	import java.net.http.HttpClient;
 11	import java.net.http.HttpRequest;
 12	import java.net.http.HttpResponse;
 13	import java.time.Duration;
 14	
 15	public final class TransLogGateway implements CarrierGateway {
 16	    private static final Duration TIMEOUT = Duration.ofSeconds(2);
 17	
 18	    private final String baseUrl;
 19	    private final HttpClient client = HttpClient.newBuilder().connectTimeout(TIMEOUT).build();
 20	    private final ObjectMapper mapper = new ObjectMapper();
 21	
 22	    public TransLogGateway(String baseUrl) {
 23	        this.baseUrl = baseUrl == null ? null : baseUrl.replaceAll("/+$", "");
 24	    }
 25	
 26	    @Override
 27	    public CarrierQuote quote(String zipCode, int weightGrams, String service) {
 28	        if (baseUrl == null || baseUrl.isBlank()) {
 29	            throw down();
 30	        }
 31	        JsonNode body;
 32	        try {
 33	            URI uri = URI.create(baseUrl + "/v2/quote?zip=" + zipCode + "&weight_g=" + weightGrams + "&service=" + service);
 34	            HttpRequest request = HttpRequest.newBuilder(uri).timeout(TIMEOUT).GET().build();
 35	            HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
 36	            if (response.statusCode() != 200) {
 37	                throw down();
 38	            }
 39	            body = mapper.readTree(response.body());
 40	        } catch (InterruptedException e) {
 41	            Thread.currentThread().interrupt();
 42	            throw down();
 43	        } catch (IOException | RuntimeException e) {
 44	            if (e instanceof ApiException api) {
 45	                throw api;
 46	            }
 47	            throw down();
 48	        }
 49	        if (body == null || !body.isObject()) {
 50	            throw down();
 51	        }
 52	        if (body.has("error")) {
 53	            if ("ZIP_NOT_SERVED".equals(body.get("error").asText())) {
 54	                throw ApiException.unprocessable("SHIPPING_METHOD_UNAVAILABLE");
 55	            }
 56	            throw down();
 57	        }
 58	        JsonNode price = body.get("price_cents");
 59	        JsonNode eta = body.get("eta_hours");
 60	        if (price == null || eta == null || !price.isIntegralNumber() || !eta.isIntegralNumber()
 61	                || !eta.canConvertToInt() || price.asLong() < 0 || eta.asInt() < 0) {
 62	            throw down();
 63	        }
 64	        return new CarrierQuote(BigDecimal.valueOf(price.asLong(), 2), eta.asInt());
 65	    }
 66	
 67	    private static ApiException down() {
 68	        return ApiException.unavailable("CARRIER_UNAVAILABLE");
 69	    }
 70	}
 71	package shop.shipping;
 72	
 73	/** Access to a carrier's quotes. Swapping carriers means a new implementation of this interface. */
 74	public interface CarrierGateway {
 75	    /**
 76	     * @param service carrier-specific service code
 77	     * @throws shop.ApiException SHIPPING_METHOD_UNAVAILABLE when the zip is not served,
 78	     *                           CARRIER_UNAVAILABLE when the carrier is down
 79	     */
 80	    CarrierQuote quote(String zipCode, int weightGrams, String service);
 81	}
 82	package shop.shipping;
 83	
 84	/** Delivery priced by a carrier; regions far from the distribution center add dispatch days. */
 85	public final class CarrierShipping implements ShippingOption {
 86	    private final String code;
 87	    private final String service;
 88	    private final CarrierGateway gateway;
 89	
 90	    public CarrierShipping(String code, String service, CarrierGateway gateway) {
 91	        this.code = code;
 92	        this.service = service;
 93	        this.gateway = gateway;
 94	    }
 95	
 96	    @Override
 97	    public String code() {
 98	        return code;
 99	    }
100	
101	    @Override
102	    public ShippingQuote quote(ShippingContext context) {
103	        CarrierQuote quote = gateway.quote(context.zipCode(), context.weightGrams(), service);
104	        int days = (quote.etaHours() + 23) / 24 + context.region().extraDispatchDays();
105	        return new ShippingQuote(quote.price(), days);
106	    }
107	}

