 83	    /** The database may still be starting when the service does, so it retries for a while. */
 84	    private static HikariDataSource connect() throws InterruptedException {
 85	        HikariConfig config = new HikariConfig();
 86	        config.setJdbcUrl(jdbcUrl(System.getenv("DB_URL")));
 87	        config.setUsername(System.getenv("DB_USER"));
 88	        config.setPassword(System.getenv("DB_PASSWORD"));
 89	        config.setMaximumPoolSize(10);
 90	        for (int attempt = 1; ; attempt++) {
 91	            try {
 92	                config.setInitializationFailTimeout(1);
 93	                return new HikariDataSource(config);
 94	            } catch (RuntimeException e) {
 95	                if (attempt >= 30) {
 96	                    throw e;
 97	                }
 98	                Thread.sleep(2000);
 99	            }
100	        }
101	    }
